defmodule ExYang.TypespecTest do
  @moduledoc false
  use ExUnit.Case, async: true

  doctest ExYang.Model.Common

  # Public functions generated by Ecto, not written here.
  @generated_modules [
    ExYang.TestRepo,
    ExYang.Registry.Migrations.V01,
    ExYang.Registry.Schema.YangDependency,
    ExYang.Registry.Schema.YangIdentity
  ]

  test "every public function in the ExYang namespace has a @spec" do
    {:ok, mods} = :application.get_key(:ex_yang, :modules)

    # A spec on resolve/2 also covers the resolve/1 generated by a default argument.
    covered? = fn specs, name, arity ->
      Enum.any?(specs, fn {{n, a}, _} -> n == name and a >= arity end)
    end

    missing =
      for mod <- mods -- @generated_modules,
          {:ok, specs} = Code.Typespec.fetch_specs(mod),
          {name, arity} <- mod.__info__(:functions),
          not String.starts_with?(Atom.to_string(name), "__"),
          not covered?.(specs, name, arity),
          do: {mod, name, arity}

    assert missing == []
  end

  test "every ExYang.Model struct declares a t() type" do
    {:ok, mods} = :application.get_key(:ex_yang, :modules)

    missing =
      for mod <- mods,
          function_exported?(mod, :__struct__, 0),
          {:ok, types} = Code.Typespec.fetch_types(mod),
          not Enum.any?(types, &match?({:type, {:t, _, _}}, &1)),
          do: mod

    assert missing == []
  end
end
